#!/bin/sh
# Writes the values nginx needs from the repo's .env into
# /etc/nginx/conf.d/kommently-env.conf and reloads nginx. Run after changing
# API_PORT or moving the repo:  sudo sh deploy/nginx/apply-env.sh
set -e
REPO=$(cd "$(dirname "$0")/../.." && pwd)
API_PORT=$(grep -E '^API_PORT=' "$REPO/.env" 2>/dev/null | tail -n1 | cut -d= -f2- | tr -d ' "\r'"'")
API_PORT=${API_PORT:-5000}
case "$API_PORT" in ''|*[!0-9]*) echo "API_PORT in .env is not a number" >&2; exit 1 ;; esac

cat > /etc/nginx/conf.d/kommently-env.conf <<CONF
# Generated by deploy/nginx/apply-env.sh from $REPO/.env; do not edit.
upstream kommently_api { server 127.0.0.1:$API_PORT; keepalive 16; }
map "" \$kommently_repo { default $REPO; }
CONF
nginx -t && systemctl reload nginx
echo "nginx: API on 127.0.0.1:$API_PORT, frontends from $REPO/{client,admin,website}/build"
